#include <iostream>
#include <mutex>
#include <thread>

struct Jar {
    int cookies;
    std::mutex lock;
};

void move_cookies(Jar& from, Jar& to, int times) {
    for (int i = 0; i < times; ++i) {
        std::scoped_lock both{from.lock, to.lock};
        --from.cookies;
        ++to.cookies;
    }
}

int main() {
    Jar red{100, {}};
    Jar blue{100, {}};
    {
        std::jthread x{move_cookies, std::ref(red), std::ref(blue), 30};
        std::jthread y{move_cookies, std::ref(blue), std::ref(red), 10};
    }
    std::cout << "red " << red.cookies << ", blue " << blue.cookies << '\n';
}

