#include <iostream>
#include <thread>
#include <vector>

int main() {
    const int cooks = 4;
    const int per_cook = 5;
    std::vector<int> first(cooks), last(cooks), sum(cooks);
    {
        std::vector<std::jthread> team;
        for (int c = 0; c < cooks; ++c) {
            team.emplace_back([&, c] {
                first[c] = c * per_cook + 1;
                last[c] = first[c] + per_cook - 1;
                for (int n = first[c]; n <= last[c]; ++n) {
                    sum[c] += n;
                }
            });
        }
    }
    for (int c = 0; c < cooks; ++c) {
        std::cout << c << ' ' << first[c] << ' ' << last[c] << ' ' << sum[c] << '\n';
    }
}

