#include <condition_variable>
#include <iostream>
#include <mutex>
#include <queue>
#include <string>
#include <thread>

std::mutex counter_lock;
std::condition_variable bell;
std::queue<std::string> ready;   // dishes waiting on the counter
bool closed = false;

void courier() {
    while (true) {
        std::unique_lock<std::mutex> hold{counter_lock};
        bell.wait(hold, [] { return !ready.empty() || closed; });
        if (ready.empty()) {
            break;                   // closed, and nothing left to serve
        }
        std::string dish = ready.front();
        ready.pop();
        hold.unlock();
        std::cout << "courier: delivering " << dish << '\n';
    }
    std::cout << "courier: kitchen closed, going home\n";
}

int main() {
    std::jthread w{courier};
    for (std::string dish : {"soup", "pasta", "cake"}) {
        {
            std::lock_guard<std::mutex> hold{counter_lock};
            ready.push(dish);
        }
        bell.notify_one();           // ding!
    }
    {
        std::lock_guard<std::mutex> hold{counter_lock};
        closed = true;
    }
    bell.notify_one();
}

