#include <vector>

int main() {
    std::vector<int> tickets(1000);
    for (int i = 0; i < 1000; ++i) {
        tickets[i] = i * 7;   // no two the same
    }

    long long pairs = 0;   // way 1: compare every pair
    for (std::size_t i = 0; i < tickets.size(); ++i) {
        for (std::size_t j = i + 1; j < tickets.size(); ++j) {
            ++pairs;
        }
    }
    std::cout << "every pair: " << pairs << " comparisons\n";

    long long lookups = 0;   // way 2: remember what you've seen
    std::unordered_set<int> seen;
    for (int t : tickets) {
        ++lookups;
        seen.insert(t);
    }
    std::cout << "a seen-set: " << lookups << " lookups\n";
}

