#include <iostream>
#include <vector>

// Three legs of a relay race. Which one is slow? Don't guess: measure.
// [[gnu::noinline]] keeps each leg a separate function, so the profiler can name it.
[[gnu::noinline]] long long warm_up(const std::vector<int>& v) {
    long long total = 0;
    for (int x : v) total += x;
    return total;
}

[[gnu::noinline]] long long find_pairs(const std::vector<int>& v) {
    long long pairs = 0;
    for (std::size_t i = 0; i < v.size(); ++i)
        for (std::size_t j = i + 1; j < v.size(); ++j)
            if (v[i] + v[j] == 100) ++pairs;
    return pairs;
}

[[gnu::noinline]] long long cool_down(const std::vector<int>& v) {
    long long biggest = 0;
    for (int x : v) if (x > biggest) biggest = x;
    return biggest;
}

int main() {
    std::vector<int> v(20000);
    for (std::size_t i = 0; i < v.size(); ++i) v[i] = static_cast<int>(i % 97);
    std::cout << warm_up(v) << ' ' << find_pairs(v) << ' ' << cool_down(v) << '\n';
}

