#include <iostream>
#include <vector>

int count_moves(bool plan_ahead) {
    std::vector<int> v;
    if (plan_ahead) {
        v.reserve(1000000);
    }
    int moves = 0;
    auto old_capacity = v.capacity();
    for (int n = 0; n < 1000000; ++n) {
        v.push_back(n);
        if (v.capacity() != old_capacity) {   // the carton grew: everything moved
            ++moves;
            old_capacity = v.capacity();
        }
    }
    return moves;
}

int main() {
    std::cout << "without reserve: " << count_moves(false) << " moves\n";
    std::cout << "with reserve:    " << count_moves(true) << " moves\n";
}

