long long sum_range(long long first, long long last) {
    long long total = 0;
    for (long long n = first; n <= last; ++n) {
        total += n;
    }
    return total;
}

int main() {
    std::vector<long long> pages(4);   // one page per cook
    {
        std::vector<std::jthread> cooks;
        for (int i = 0; i < 4; ++i) {
            long long first = i * 100000LL + 1;
            cooks.emplace_back([&pages, i, first] {
                pages[i] = sum_range(first, first + 99999);
            });
        }
    }   // all four jthreads join here
    long long total = 0;
    for (int i = 0; i < 4; ++i) {
        std::cout << "cook " << i << " wrote " << pages[i] << '\n';
        total += pages[i];
    }
    std::cout << "total: " << total << '\n';
}

