struct Shelf {
    int eggs;
    std::mutex lock;
};

void move_eggs(Shelf& from, Shelf& to, int times) {
    for (int i = 0; i < times; ++i) {
        std::scoped_lock both{from.lock, to.lock};   // both at once
        --from.eggs;
        ++to.eggs;
    }
}

int main() {
    Shelf fridge{50, {}};
    Shelf pantry{50, {}};
    {
        std::jthread cook1{move_eggs, std::ref(fridge), std::ref(pantry), 1000};
        std::jthread cook2{move_eggs, std::ref(pantry), std::ref(fridge), 1000};
    }
