#include <chrono>
#include <iostream>
#include <list>
#include <numeric>
#include <vector>

template <typename Container>
void time_sum(const char* name, const Container& c) {
    auto start = std::chrono::steady_clock::now();
    long long total = std::accumulate(c.begin(), c.end(), 0LL);
    auto stop = std::chrono::steady_clock::now();
    auto us = std::chrono::duration_cast<std::chrono::microseconds>(stop - start);
    std::cout << name << ": total " << total << ", took " << us.count() << " us\n";
}

int main() {
    std::vector<int> row(2000000, 1);
    std::list<int> chain(2000000, 1);
    time_sum("vector", row);
    time_sum("list  ", chain);
}
